{
  "outcome": "deny",
  "rationale": "We deny this claim because the automated findings and the claimant's account confirm the driver was operating the vehicle over the legal alcohol limit. This loss is excluded under Section 4, Impaired Driving.",
  "citations": [
    {
      "clause_id": "STD-4.6",
      "quote": "We do not cover loss that occurs while the driver of the covered vehicle is under the influence of alcohol, a controlled substance or any drug that impairs driving ability, including any case in which the driver's measured blood alcohol concentration exceeds the legal limit of the state where the loss occurred."
    }
  ]
}
